package com.hbm.client.gascentrifuge;
import com.hbm.client.model.*;import com.hbm.machine.gascentrifuge.*;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;
/** Source smooth RenderCentrifuge gas branch: whole fixed vessel+flag, yaw plus180, no invented rotor. */
public final class GasCentrifugeRenderer implements BlockEntityRenderer<GasCentrifugeBlockEntity> {
 static final ResourceLocation MODEL=GasCentrifugeContent.id("models/machines/gascent.obj"),TEXTURE=GasCentrifugeContent.id("textures/models/machines/gascent.png");public GasCentrifugeRenderer(BlockEntityRendererProvider.Context context){}static void model(PoseStack poses,MultiBufferSource buffers,int light,int overlay,boolean flag){LegacyObjRenderer.renderOnly(LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL),poses,buffers.getBuffer(RenderType.entityCutoutNoCull(TEXTURE)),light,overlay,-1,LegacyObjRenderer.Convention.HFR,flag?new String[]{"Centrifuge","Flag"}:new String[]{"Centrifuge"});}
 @Override public void render(GasCentrifugeBlockEntity machine,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){int angle=180+switch(DummyableBlock.facing(machine.getBlockState())){case NORTH->90;case WEST->180;case SOUTH->270;default->0;};LegacyContactShadows.render(machine,LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL),new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(angle)),poses,buffers);poses.pushPose();poses.translate(.5,0,.5);poses.mulPose(Axis.YP.rotationDegrees(angle));model(poses,buffers,light,overlay,true);poses.popPose();}@Override public boolean shouldRenderOffScreen(GasCentrifugeBlockEntity machine){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(GasCentrifugeBlockEntity machine){var p=machine.getBlockPos();return new AABB(p.getX(),p.getY(),p.getZ(),p.getX()+1,p.getY()+5,p.getZ()+1);}
}
